import{_ as t,o as r,c as o,a5 as s}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-21-remove-workspace-member/report3_spec.md","filePath":"feature/agency-workspace/3-4-21-remove-workspace-member/report3_spec.md"}'),i={name:"feature/agency-workspace/3-4-21-remove-workspace-member/report3_spec.md"};function a(n,e,l,m,h,c){return r(),o("div",null,[...e[0]||(e[0]=[s("<p><strong>3.4.21 Remove Workspace Member</strong></p><p><strong>Function Trigger</strong></p><p>Begins when the MANAGER of a Workspace confirms removal of a member from that Workspace.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: The MANAGER of the Workspace, and only that role.</li><li><strong>Purpose</strong>: Lets the MANAGER take a member out of the Workspace while the member stays in the Agency and can still join other Workspaces.</li><li><strong>Interface</strong>: A Remove action per member in the member table, followed by a confirmation dialog.</li><li><strong>Data Processing</strong>: The system loads the member, applies the last-MANAGER guard, and marks the membership inactive without touching the member&#39;s Agency membership.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Remove Member Dialog:</p><ul><li>A Remove action per member in the members table.</li><li>A confirmation dialog naming the member being removed.</li><li>A blocked state with a clear message when the member is the only active MANAGER of the Workspace.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the member identifier; the caller&#39;s authenticated identity.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: the caller&#39;s role in the Workspace; the member record and its role; the count of active MANAGERs in the Workspace.</li><li><strong>Output</strong>: confirmation that the membership has been deactivated; no other data is returned.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-35</strong>: The role check re-reads the caller&#39;s role from the DB at request time; SystemRole.ADMIN bypasses the check. Only MANAGER may remove a member; any other caller -&gt; 403 FORBIDDEN. Runs before any service-level guard.</li><li><strong>BR-28</strong>: Remove member - only MANAGER may remove; the last remaining active MANAGER cannot be removed or changed away from MANAGER; removal is a soft-delete (isActive=false), not a row deletion. The member&#39;s Agency membership is never modified.</li><li><strong>BR-30</strong>: A removed member loses access immediately because every scoped query re-checks membership.</li><li><strong>BR-28 (last-MANAGER guard)</strong>: removing a member whose role is MANAGER is blocked with 409 LAST_MANAGER_CANNOT_BE_REMOVED when that member is the only active MANAGER of the Workspace. The same guard is shared with FR 3.4.16 Leave Workspace and FR 3.4.20 Update Workspace Member Role.</li><li><strong>BR-29</strong>: The member lookup is scoped to the Workspace; a member that does not exist, is not active, or belongs to another Workspace -&gt; 404 NOT_FOUND.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller must be the MANAGER of that Workspace; otherwise 403 FORBIDDEN. Toast <strong>MSG39</strong>.</li><li>The member must exist, be active, and belong to that Workspace; otherwise 404 NOT_FOUND. Toast <strong>MSG38</strong>.</li><li>Removing the only active MANAGER of the Workspace -&gt; 409 LAST_MANAGER_CANNOT_BE_REMOVED. Toast <strong>MSG37</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>MANAGER opens the members screen and chooses Remove for a member.</li><li>MANAGER confirms in the dialog.</li><li>System confirms the caller holds the MANAGER role in that Workspace; otherwise the request fails with 403 FORBIDDEN.</li><li>System loads the member and checks that it exists, is active, and belongs to that Workspace; otherwise the request fails with 404 NOT_FOUND.</li><li>System applies the last-MANAGER guard: members who are not MANAGER pass, and a MANAGER passes only when another active MANAGER exists.</li><li>System marks the membership inactive; the member disappears from the active member list; toast <strong>MSG36</strong>.</li><li>The member&#39;s Agency membership is untouched - they remain in the Agency and in any other Workspace they take part in.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Caller is not the MANAGER of that Workspace -&gt; 403 FORBIDDEN, toast <strong>MSG39</strong>. 3.a2: The screen blocks the action.</li><li>4.a1: Member does not exist, is not active, or belongs to another Workspace -&gt; 404 NOT_FOUND, toast <strong>MSG38</strong>. 4.a2: The screen refreshes the member list.</li><li>5.a1: Removing the only active MANAGER of the Workspace -&gt; 409 LAST_MANAGER_CANNOT_BE_REMOVED, toast <strong>MSG37</strong>. 5.a2: The MANAGER assigns another member as MANAGER first, then retries the removal.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The member&#39;s membership in the Workspace is inactive and the Workspace no longer appears in their list.</li><li>The member&#39;s Agency membership is untouched; they remain in the Agency and in their other Workspaces.</li><li>The Workspace still has exactly one active MANAGER.</li></ul>",14)])])}const A=t(i,[["render",a]]);export{g as __pageData,A as default};
